class Solution {
    public boolean halvesAreAlike(String text){
        String vowels="aeiouAEIOU";
        int difference=0;
        for(int i=0;i<text.length();i++)if(vowels.indexOf(text.charAt(i))>=0)difference+=i<text.length()/2?1:-1;
        return difference==0;
    }
}

code.kotlin:
class Solution {
    fun halvesAreAlike(text:String):Boolean{
        val vowels="aeiouAEIOU";
        var difference=0;
        for(i in text.indices)if(text[i] in vowels)difference+=if(i<text.length/2)1 else -1;
        return difference==0
    }
}

code.cpp:
class Solution {
    public: bool halvesAreAlike(string text){
        string vowels="aeiouAEIOU";
        int difference=0;
        for(int i=0;i<(int)text.size();++i)if(vowels.find(text[i])!=string::npos)difference+=i<(int)text.size()/2?1:-1;
        return difference==0;
    }
};
